<?php
namespace Modules\Cutting\Services;

use Illuminate\Support\Facades\DB;use Modules\Core\Approval\ApprovalEngine;use Modules\Core\Models\ApprovalRequest;use Modules\Core\Models\User;use Modules\Core\Services\AuditService;use Modules\Cutting\Models\Bundle;use Modules\Cutting\Models\CustomerShadeRule;use Modules\Cutting\Models\CutOrder;use Modules\Cutting\Models\CutOrderLine;use Modules\Cutting\Models\CutOutput;use Modules\Cutting\Models\Lay;use Modules\Cutting\Models\LayRoll;use Modules\Cutting\Models\ShadeOverrideRequest;use Modules\MasterData\Models\Customer;use Modules\MasterData\Services\UomConversionService;use Modules\Receiving\Models\FabricRoll;use RuntimeException;

class LayExecutionService
{
 public function __construct(private ApprovalEngine $approval,private AuditService $audit,private UomConversionService $uoms){}
 public function configureBuyer(Customer $customer,bool $enabled,User $user):CustomerShadeRule{return DB::transaction(function()use($customer,$enabled,$user){$c=Customer::withoutGlobalScopes()->whereKey($customer->id)->lockForUpdate()->firstOrFail();$this->access($user,(int)$c->company_id);$rule=CustomerShadeRule::withoutGlobalScopes()->updateOrCreate(['company_id'=>$c->company_id,'customer_id'=>$c->id],['enabled'=>$enabled,'updated_by'=>$user->id,'created_by'=>$user->id]);$this->audit->record('update',$rule,after:['enabled'=>$enabled]);return$rule;});}
 public function buyerRule(Customer $customer,User $user):array{$c=Customer::withoutGlobalScopes()->whereKey($customer->id)->firstOrFail();$this->access($user,(int)$c->company_id);$r=CustomerShadeRule::withoutGlobalScopes()->where('company_id',$c->company_id)->where('customer_id',$c->id)->first();return['customer_id'=>$c->id,'enabled'=>$r?->enabled??true,'configured'=>$r!==null];}
 public function createLay(CutOrder $cut,int $layers,User $user):Lay{return DB::transaction(function()use($cut,$layers,$user){if($layers<1)throw new RuntimeException('Layer count wajib minimal 1.');$co=CutOrder::withoutGlobalScopes()->with('productionOrder.salesOrder')->whereKey($cut->id)->lockForUpdate()->firstOrFail();$this->access($user,(int)$co->company_id);if($co->status!=='IN_PROGRESS')throw new RuntimeException('Lay hanya dapat dibuat pada cut order IN_PROGRESS.');$customerId=(int)$co->productionOrder->salesOrder->customer_id;$rule=CustomerShadeRule::withoutGlobalScopes()->where('company_id',$co->company_id)->where('customer_id',$customerId)->first();$seq=Lay::withoutGlobalScopes()->where('cut_order_id',$co->id)->count()+1;$lay=Lay::create(['company_id'=>$co->company_id,'cut_order_id'=>$co->id,'lay_no'=>$co->doc_no.'-LAY-'.str_pad((string)$seq,3,'0',STR_PAD_LEFT),'layer_count'=>$layers,'lay_date'=>now()->toDateString(),'shade_validation_enabled'=>$rule?->enabled??true,'status'=>'DRAFT','created_by'=>$user->id]);$this->audit->record('create',$lay,after:['shade_validation_enabled'=>$lay->shade_validation_enabled]);return$lay;});}
 public function list(CutOrder $cut,User $user){$co=CutOrder::withoutGlobalScopes()->whereKey($cut->id)->firstOrFail();$this->access($user,(int)$co->company_id);return Lay::withoutGlobalScopes()->where('company_id',$co->company_id)->where('cut_order_id',$co->id)->with(['shadeGroup','rolls.fabricRoll.shadeGroup','cutOutputs.cutOrderLine','cutOutputs.bundles','overrideRequests.approvalRequest'])->orderBy('id')->get();}
 public function addRoll(Lay $lay,FabricRoll $roll,float $qty,User $user):LayRoll{return $this->addRollInternal($lay,$roll,$qty,$user,false);}
 public function requestOverride(Lay $lay,FabricRoll $roll,float $qty,string $reason,User $user):ShadeOverrideRequest{return DB::transaction(function()use($lay,$roll,$qty,$reason,$user){if(trim($reason)===''||$qty<=0)throw new RuntimeException('Reason dan qty override wajib diisi.');[$locked,$r,$dispatch,$uom]=$this->context($lay,$roll,$qty,$user);if(!$locked->shade_validation_enabled)throw new RuntimeException('Override tidak diperlukan karena BR-053 nonaktif.');if(!$this->mismatch($locked,$r))throw new RuntimeException('Roll compatible; override tidak diperlukan.');$this->eligible($r,$dispatch,$qty);$o=ShadeOverrideRequest::create(['company_id'=>$locked->company_id,'lay_id'=>$locked->id,'fabric_roll_id'=>$r->id,'uom_id'=>$uom,'qty_used'=>$qty,'reason'=>$reason,'status'=>'PENDING','requested_by'=>$user->id]);$approval=$this->approval->submit($o,'SHADE_OVERRIDE',$user);$o->update(['approval_request_id'=>$approval->id]);$this->audit->record('submit',$o,after:['reason'=>$reason,'approval_request_id'=>$approval->id]);return$o->fresh('approvalRequest');});}
 public function applyOverride(ShadeOverrideRequest $override,User $user):LayRoll{return DB::transaction(function()use($override,$user){$o=ShadeOverrideRequest::withoutGlobalScopes()->whereKey($override->id)->lockForUpdate()->firstOrFail();$this->access($user,(int)$o->company_id);if($o->status==='APPLIED')throw new RuntimeException('Override sudah diterapkan.');$approval=ApprovalRequest::withoutGlobalScopes()->where('company_id',$o->company_id)->whereKey($o->approval_request_id)->where('doc_type','SHADE_OVERRIDE')->where('doc_id',$o->id)->first();if(!$approval||$approval->status!=='APPROVED')throw new RuntimeException('Lay Roll tetap BLOCKED sampai ApprovalEngine APPROVED.');$line=$this->addRollInternal($o->lay,$o->fabricRoll,(float)$o->qty_used,$user,true);$o->update(['status'=>'APPLIED','applied_by'=>$user->id,'applied_at'=>now()]);$this->audit->record('apply',$o,after:['lay_roll_id'=>$line->id]);return$line;});}
 public function createOutput(Lay $lay,int $lineId,float $qty,User $user):CutOutput{return DB::transaction(function()use($lay,$lineId,$qty,$user){if($qty<=0)throw new RuntimeException('Cut output wajib lebih besar dari nol.');$l=Lay::withoutGlobalScopes()->with('cutOrder')->whereKey($lay->id)->lockForUpdate()->firstOrFail();$this->access($user,(int)$l->company_id);if($l->status!=='IN_PROGRESS'||$l->cutOrder->status!=='IN_PROGRESS')throw new RuntimeException('Cut output hanya untuk Lay dan Cut Order IN_PROGRESS.');if($l->rolls()->count()===0)throw new RuntimeException('Cut output memerlukan minimal satu Lay Roll.');$line=CutOrderLine::query()->where('cut_order_id',$l->cut_order_id)->whereKey($lineId)->lockForUpdate()->firstOrFail();$existing=(float)CutOutput::withoutGlobalScopes()->where('cut_order_line_id',$line->id)->sum('qty_cut');if($existing+$qty-(float)$line->qty_cut>0.0001)throw new RuntimeException('Cut output melebihi qty Cut Order Line.');$out=CutOutput::create(['company_id'=>$l->company_id,'lay_id'=>$l->id,'cut_order_line_id'=>$line->id,'qty_cut'=>$qty,'created_by'=>$user->id]);$this->audit->record('create',$out,after:['qty_cut'=>$qty]);return$out;});}
 public function generateBundles(CutOutput $output,int $size,User $user):array{return DB::transaction(function()use($output,$size,$user){if($size<1)throw new RuntimeException('Bundle size wajib minimal 1.');$out=CutOutput::withoutGlobalScopes()->with(['lay.cutOrder','cutOrderLine'])->whereKey($output->id)->lockForUpdate()->firstOrFail();$this->access($user,(int)$out->company_id);if($out->lay->status!=='IN_PROGRESS'||$out->lay->cutOrder->status!=='IN_PROGRESS')throw new RuntimeException('Bundle hanya dapat dibuat dari Lay dan Cut Order IN_PROGRESS.');if($out->bundles()->exists())throw new RuntimeException('Bundle untuk Cut Output sudah dibuat.');$remaining=(float)$out->qty_cut;$seq=0;$rows=[];while($remaining>0.0001){$qty=min((float)$size,$remaining);$seq++;$rows[]=Bundle::create(['company_id'=>$out->company_id,'bundle_no'=>$out->lay->lay_no.'-O'.$out->id.'-B'.str_pad((string)$seq,3,'0',STR_PAD_LEFT),'cut_order_line_id'=>$out->cut_order_line_id,'cut_output_id'=>$out->id,'production_order_id'=>$out->lay->cutOrder->production_order_id,'qty'=>$qty,'current_stage'=>'CUTTING','status'=>'ACTIVE']);$remaining=round($remaining-$qty,4);}$this->audit->record('update',$out,after:['bundles_created'=>count($rows),'bundle_qty'=>(float)$out->qty_cut]);return$rows;});}
 public function completeLay(Lay $lay,User $user):Lay{return DB::transaction(function()use($lay,$user){$l=Lay::withoutGlobalScopes()->with(['rolls.fabricRoll','cutOutputs.bundles','cutOrder'])->whereKey($lay->id)->lockForUpdate()->firstOrFail();$this->access($user,(int)$l->company_id);if($l->status!=='IN_PROGRESS'||$l->cutOrder->status!=='IN_PROGRESS')throw new RuntimeException('Hanya Lay dan Cut Order IN_PROGRESS yang dapat diselesaikan.');if($l->rolls->isEmpty()||$l->cutOutputs->isEmpty())throw new RuntimeException('Lay memerlukan Lay Roll dan Cut Output.');foreach($l->cutOutputs as$o)if(abs((float)$o->bundles->sum('qty')-(float)$o->qty_cut)>0.0001)throw new RuntimeException('Bundle wajib sama dengan Cut Output.');$this->assertNoMarkerConsumption((int)$l->cutOrder->production_order_id);$l->update(['status'=>'COMPLETED','updated_by'=>$user->id]);$this->syncActualConsumption((int)$l->cutOrder->production_order_id);$this->audit->record('update',$l,after:['status'=>'COMPLETED','consumption_path'=>'LAY_ROLL']);return$l->fresh(['rolls.fabricRoll','cutOutputs.bundles']);});}
 private function addRollInternal(Lay $lay,FabricRoll $roll,float $qty,User $user,bool $override):LayRoll{return DB::transaction(function()use($lay,$roll,$qty,$user,$override){[$l,$r,$dispatch,$uom]=$this->context($lay,$roll,$qty,$user);if($l->shade_validation_enabled&&$this->mismatch($l,$r)&&!$override)throw new RuntimeException('BR-053 BLOCK: shade group incompatible; controlled override required.');$this->eligible($r,$dispatch,$qty);$meters=$this->uoms->toMeters((int)$l->company_id,$uom,$qty);$line=LayRoll::create(['company_id'=>$l->company_id,'lay_id'=>$l->id,'fabric_roll_id'=>$r->id,'uom_id'=>$uom,'qty_used'=>$qty,'shade_override'=>$override,'created_by'=>$user->id]);DB::table('fabric_dispatch_balances')->where('id',$dispatch->id)->update(['qty_consumed'=>(float)$dispatch->qty_consumed+$qty,'updated_at'=>now()]);$r->consumeUse($qty,$meters);$update=['status'=>'IN_PROGRESS','updated_by'=>$user->id];if($l->shade_validation_enabled&&$l->shade_group_id===null&&$r->shade_group_id!==null)$update['shade_group_id']=$r->shade_group_id;$l->update($update);$this->audit->record('create',$line,after:['qty_used'=>$qty,'uom_id'=>$uom,'shade_override'=>$override,'consumption_path'=>'LAY_ROLL']);return$line;});}
 private function context(Lay $lay,FabricRoll $roll,float $qty,User $user):array{if($qty<=0)throw new RuntimeException('Lay Roll qty wajib lebih besar dari nol.');$l=Lay::withoutGlobalScopes()->with('cutOrder')->whereKey($lay->id)->lockForUpdate()->firstOrFail();$this->access($user,(int)$l->company_id);if(!in_array($l->status,['DRAFT','IN_PROGRESS'],true)||$l->cutOrder->status!=='IN_PROGRESS')throw new RuntimeException('Lay Roll hanya untuk Lay dan Cut Order aktif.');$this->assertNoMarkerConsumption((int)$l->cutOrder->production_order_id);$r=FabricRoll::withoutGlobalScopes()->with('material')->where('company_id',$l->company_id)->whereKey($roll->id)->lockForUpdate()->first();if(!$r||$r->status!=='RELEASED')throw new RuntimeException('Fabric Roll tidak valid atau belum RELEASED.');$dispatch=DB::table('fabric_dispatch_balances')->where('company_id',$l->company_id)->where('production_order_id',$l->cutOrder->production_order_id)->where('roll_id',$r->id)->lockForUpdate()->first();if(!$dispatch)throw new RuntimeException('Fabric Roll belum allocated/issued ke MO.');$uom=(int)($r->use_uom_id?:$r->material->use_uom_id);if($uom!==(int)$dispatch->uom_id)throw new RuntimeException('Lay Roll wajib memakai Fabric Roll use-UOM.');return[$l,$r,$dispatch,$uom];}
 private function mismatch(Lay $l,FabricRoll $r):bool{if($r->shade_group_id===null)return true;if($l->shade_group_id===null)return false;return(int)$l->shade_group_id!==(int)$r->shade_group_id;}
 private function eligible(FabricRoll $r,object $d,float $qty):void{$available=round((float)$d->qty_dispatched-(float)$d->qty_consumed-(float)$d->qty_returned,4);if($qty-$available>0.0001)throw new RuntimeException('Lay Roll melebihi eligible dispatched quantity.');if($qty-$r->remainingUse()>0.0001)throw new RuntimeException('Lay Roll melebihi physical remaining quantity.');}
 private function syncActualConsumption(int $moId):void{$usage=DB::table('lay_rolls')->join('fabric_rolls','fabric_rolls.id','=','lay_rolls.fabric_roll_id')->join('lays','lays.id','=','lay_rolls.lay_id')->join('cut_orders','cut_orders.id','=','lays.cut_order_id')->where('cut_orders.production_order_id',$moId)->selectRaw('fabric_rolls.material_id,SUM(lay_rolls.qty_used) used')->groupBy('fabric_rolls.material_id')->get();$pcs=(float)DB::table('cut_outputs')->join('lays','lays.id','=','cut_outputs.lay_id')->join('cut_orders','cut_orders.id','=','lays.cut_order_id')->where('cut_orders.production_order_id',$moId)->sum('cut_outputs.qty_cut');foreach($usage as$u)DB::table('mo_material_allocations')->where('production_order_id',$moId)->where('material_id',$u->material_id)->update(['qty_consumed'=>$u->used,'actual_consumption_per_pcs'=>$pcs>0?round((float)$u->used/$pcs,6):null,'updated_at'=>now()]);}
 private function assertNoMarkerConsumption(int $moId):void{if(DB::table('marker_logs')->join('cut_orders','cut_orders.id','=','marker_logs.cut_order_id')->where('cut_orders.production_order_id',$moId)->exists())throw new RuntimeException('CUTTING_CONSUMPTION_CONFLICT: legacy Marker consumption sudah ada pada MO; Lay Roll consumption diblokir sampai authority decision LOCKED.');}
 private function access(User $u,int$company):void{if((int)$u->company_id!==$company&&!$u->companies()->whereKey($company)->exists())throw new RuntimeException('User tidak memiliki akses ke company Lay.');}
}
